package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// RealClock uses the system clock.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	clock    Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New returns a Limiter with a full bucket. rate is tokens per second;
// burst is the maximum bucket size.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}

	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (approximate
// under concurrency; refills lazily to now).
func (l *Limiter) Tokens() float64 {
	return l.tokens
}
